import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.DNWSvgyB.png",_=JSON.parse('{"title":"移动端 OA","description":"","frontmatter":{},"headers":[],"relativePath":"oa/mobile.md","filePath":"oa/mobile.md","lastUpdated":null}'),c={name:"oa/mobile.md"};function t(r,e,n,p,s,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="移动端-oa" tabindex="-1">移动端 OA <a class="header-anchor" href="#移动端-oa" aria-label="Permalink to &quot;移动端 OA&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的 OA 系统，重点说清楚两件事：OA 已经提供手机端、当前支持的主要功能。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-oa</code> 模块与 <code>/oa/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><p>工作台「OA 办公协同」的菜单与 PC 管理后台对齐，分组如下：</p><ul><li>公告管理：我收到的、我发布的。</li><li>讨论区：讨论区。</li><li>企业云盘：企业云盘。</li><li>企业邮箱：企业邮箱。</li><li>通讯录：联系人。</li><li>笔记管理：笔记。</li><li>日程管理：日程。</li><li>工作计划：计划管理、计划报表。</li><li>任务管理：我的任务、我发布的。</li><li>工作汇报：我的汇报、汇报统计。</li><li>考勤管理：我的考勤、团队考勤、考勤报表。</li><li>流程管理：请假申请、加班申请、转正申请、离职申请、费用报销。</li><li>车辆管理：车辆信息、用车申请、还车申请。</li><li>会议室管理：会议室信息、会议室预定。</li><li>办公用品：用品管理、领用申请、领用发放。</li><li>印章管理：印章信息、用印申请。</li><li>出差管理：出差申请、差旅报销。</li><li>公文管理：套红模板、公文发文、公文收文。</li></ul><p><img src="'+d+'" alt="OA 移动端工作台"></p><p>进入工作台后，点击「OA 办公协同」即可看到功能分组；页面路由为 <code>/pages/index/index</code>，OA 菜单由 <code>src/pages/index/menu.json</code> 的 <code>oa</code> 分组配置，按当前账号的 <code>oa:*</code> 权限过滤。移动端页面统一位于 <code>src/pages-oa</code>，并通过 <code>src/api/oa</code> 调用后端。</p><h2 id="_2-启动与发布" tabindex="-1">2. 启动与发布 <a class="header-anchor" href="#_2-启动与发布" aria-label="Permalink to &quot;2. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档。</li></ul><p>启动完成后，在工作台选择「OA 办公协同」即可进入。</p><p>别忘了先开启 OA 模块</p><p>移动端复用后端同一套接口，因此 <a href="./build">《功能开启》</a> 里的模块启用和 SQL 导入同样是前提。工作台按当前账号的菜单权限展示业务入口。</p><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-oa/</code></li><li>接口：<code>src/api/oa/</code></li><li>菜单：<code>src/pages/index/menu.json</code> 的 <code>oa</code> 分组</li></ul>',16)])])}const m=a(c,[["render",t]]);export{_ as __pageData,m as default};
